#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    int t;
    cin >> t;
    while(t--){
        int n;
        cin >> n;
        
        vector<int> a(n);
        int val=INT_MAX;
        for(int i=0;i<n;++i){
            cin >> a[i];
        }
        
        if(n==2){
            cout << a[1]-a[0] << "\n";
            continue;
        }
        
        vector<int> diff;
        for(int i=0;i<n-1;++i){
            diff.push_back(abs(a[i+1]-a[i]));
        }
        
        diff.push_back(abs(a[n-1]-a[0]));
        sort(diff.begin(),diff.end());
        
        cout << diff[diff.size()-2] << "\n";
        
    }
}
